/*
# Testing module — seed catalog data

Seeds the QA test catalog (21 modules, 302 test cases) extracted from the previous
version of the testing page into `test_modules` / `test_cases`. Definitions-only data,
no security changes. Idempotent: existing rows are updated on conflict, none are deleted.
*/

ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, scope=EXCLUDED.scope;

ON CONFLICT (test_case_id) DO UPDATE SET
  module_code=EXCLUDED.module_code, title=EXCLUDED.title, priority=EXCLUDED.priority,
  description=EXCLUDED.description, feature=EXCLUDED.feature, sort_order=EXCLUDED.sort_order;